from pathlib import Path
import json,hashlib,subprocess,copy,re
R=Path.cwd();W=R/'memo-os/week-9';BASE='42c0f1de5cd7bc876a33dda647224bc120852f7a'
pf=W/'WEEK_9_COMPLETE_ISSUE_PREVIS_2026-11-08.json';cf=W/'WEEK_9_SPORTS_STORY_CARDS_2026-11-08.json'
D=json.loads(pf.read_text());C=json.loads(cf.read_text())
B=json.loads(subprocess.check_output(['git','show',BASE+':'+str(pf.relative_to(R))],text=True));BC=json.loads(subprocess.check_output(['git','show',BASE+':'+str(cf.relative_to(R))],text=True))
contract=(R/'memo-os/PAGE_PRODUCTION_CONTRACT_V1.md').read_text().split('```yaml\n')[1].split('```')[0]
required=set(re.findall(r'^([a-z_]+):',contract,re.M))
def check(d,c):
 err=[];pages=d['pages'];cards=c['cards'];pm={p['page_id']:p for p in pages};pids=set(pm)
 if len(pages)!=28 or len(pids)!=28:err.append('PAGE_SET')
 for p in pages:
  if not required<=set(p):err.append('CONTRACT_FIELDS')
  if [p['output_width_px'],p['output_height_px']]!=[1080,1920]:err.append('GEOMETRY')
  if p['render_authorized'] or p['page_state']!='PLANNED' or p['actual_winner_team_id'] is not None:err.append('PREMATURE_PROMOTION')
  for neighbour in p['adjacent_pages'].values():
   if neighbour is not None and neighbour not in pids:err.append('ADJACENCY')
 if len(cards)!=6 or {x['id'] for x in cards}!={f'W09-M0{i}' for i in range(1,7)}:err.append('SIX_MATCHUPS')
 all_beats=[]
 for card,original in zip(cards,BC['cards']):
  if card['home']!=original['home'] or card['away']!=original['away']:err.append('SOURCE_IDENTITY_RECORD')
  if card['sports_causality']!=original['sports_causality']:err.append('SPORTS_DATA_MUTATED')
  if not card.get('home_win') or not card.get('away_win'):err.append('OUTCOME_MISSING')
  ss=card['written_storyboard_sequence'];beats=ss['beats'];all_beats+=beats
  if sum(b['branch']=='HOME_WIN' for b in beats)!=1 or sum(b['branch']=='AWAY_WIN' for b in beats)!=1:err.append('BRANCH_PAIR')
  if not ss['ground_plan'] or len(ss['persistent_scene_anchors'])!=3:err.append('GROUND_PLAN')
  for b in beats:
   if b['page_id'] not in pm or pm[b['page_id']].get('matchup_id')!=card['id']:err.append('WRONG_PAGE_BINDING');continue
   if any(not b.get(k) for k in ['shot','pose_and_physical_action','what_changes','transition']):err.append('EMPTY_BEAT')
   if b not in pm[b['page_id']]['written_storyboard']['beats']:err.append('CARD_PAGE_DRIFT')
 if len(all_beats)!=48 or len({b['beat_id'] for b in all_beats})!=48:err.append('BEAT_SET')
 if sum(b['branch']=='COMMON' for b in all_beats)!=36:err.append('COMMON_COUNT')
 if len([p for p in pages if p.get('written_storyboard')])!=18:err.append('CINEMATIC_COVERAGE')
 for p in B['pages']:
  if not p.get('matchup_id') and pm[p['page_id']]!=p:err.append('EDITORIAL_DEPARTMENT_MUTATED')
 for pid in ['W09-P05','W09-P20']:
  p=pm[pid]
  if p['character_exception_dependencies']:err.append('OUTLIER_LEAK')
  if p['proof_preparation']['character_reconfirmation_required']:err.append('IDENTITY_REOPENED')
  if p['proof_preparation']['storyboard_beat_ids']!=[x['beat_id'] for x in p['written_storyboard']['beats']]:err.append('PROOF_SEQUENCE_DRIFT')
  for a in p['reference_assets']:
   v=a['selected_visual_reference'];path=R/v['path']
   if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest()!=v['sha256']:err.append('REFERENCE_HASH')
 if 'horns/build' in cards[-1]['physical_direction']:err.append('STALE_SLOB')
 hold=d['all_phases_execution']['sports_desk_hold']
 if hold['live_refresh_performed'] or len(hold['fields_held'])!=7:err.append('SPORTS_HOLD')
 if hashlib.sha256((R/hold['source_path']).read_bytes()).hexdigest()!=hold['source_sha256']:err.append('SOURCE_HASH')
 return sorted(set(err))
assert check(D,C)==[],check(D,C)
negative=[]
def mutate(name,fn):
 a,b=copy.deepcopy(D),copy.deepcopy(C);fn(a,b);errors=check(a,b);assert errors,name;negative.append({'case':name,'rejected_by':errors})
mutate('remove_away_ending',lambda a,b:b['cards'][0]['written_storyboard_sequence']['beats'].pop())
mutate('wrong_storyboard_page',lambda a,b:b['cards'][0]['written_storyboard_sequence']['beats'][0].update(page_id='W09-P20'))
mutate('invent_final_winner',lambda a,b:a['pages'][6].update(actual_winner_team_id=1))
mutate('authorize_render_without_execution',lambda a,b:a['pages'][4].update(render_authorized=True))
mutate('mutate_entering_record',lambda a,b:b['cards'][0]['home'].update(record='6-3'))
mutate('invent_player_cause',lambda a,b:b['cards'][0]['sports_causality'].update(player_contributors=['invented']))
mutate('leak_DK_exception',lambda a,b:a['pages'][4]['character_exception_dependencies'].append('CHAR-WILSON-LOOK'))
mutate('reopen_settled_identity',lambda a,b:a['pages'][19]['proof_preparation'].update(character_reconfirmation_required=True))
mutate('false_live_refresh',lambda a,b:a['all_phases_execution']['sports_desk_hold'].update(live_refresh_performed=True))
mutate('wrong_output_geometry',lambda a,b:a['pages'][4].update(output_width_px=1024))
receipt_path=W/'production-evidence/WEEK_9_ALL_PHASES_EXECUTION_2026-11-08.json';receipt=json.loads(receipt_path.read_text())
receipt['validation']={'state':'STRUCTURAL_SOURCE_CONSISTENCY_PASS_NOT_VISUAL_OR_RELEASE_ACCEPTANCE','base_commit':BASE,'pages':28,'required_fields_per_page':len(required),'cinematic_pages':18,'editorial_pages_unchanged':10,'sequences':6,'beats':48,'common_beats':36,'conditional_endings':12,'approved_proof_reference_hash_matches':4,'sports_fields_unchanged':True,'negative_cases':negative,'command':'python3 /tmp/verify-week9-all-phases-20261108.py','verification_source':Path(__file__).read_text(),'visual_test_performed':False,'images_generated':0}
receipt_path.write_text(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({k:v for k,v in receipt['validation'].items() if k!='verification_source'},indent=2))
